BEGIN;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM project_issues) OR EXISTS (SELECT 1 FROM project_deliverables) OR EXISTS (SELECT 1 FROM system_workflows WHERE revision <> 1) THEN
    RAISE EXCEPTION 'Workflow responsibilities require fresh issue and delivery data; existing business data is not converted.';
  END IF;
END $$;
ALTER TABLE project_issues DROP COLUMN participant_ids, DROP COLUMN assignee_id,
  ADD COLUMN developer_id TEXT, ADD COLUMN reporter_id TEXT NOT NULL,
  ADD COLUMN business_owner_id TEXT NOT NULL, ADD COLUMN qa_owner_id TEXT,
  ADD COLUMN acceptance_owner_id TEXT, ADD COLUMN watcher_ids TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[];
ALTER TABLE project_deliverables ADD COLUMN reviewer_id TEXT NOT NULL,
  ADD COLUMN verification_started_at TIMESTAMPTZ(3), ADD COLUMN supersedes_id TEXT;
CREATE UNIQUE INDEX project_deliverables_supersedes_id_key ON project_deliverables(supersedes_id);
ALTER TABLE project_deliverables ADD CONSTRAINT project_deliverables_supersedes_id_fkey FOREIGN KEY (supersedes_id) REFERENCES project_deliverables(id) ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE work_actions (
  id TEXT PRIMARY KEY, project_id TEXT NOT NULL, issue_id TEXT NOT NULL,
  workflow_version_id TEXT NOT NULL, node_id TEXT NOT NULL, sequence INTEGER NOT NULL,
  handler_id TEXT NOT NULL, category TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ready',
  revision INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  started_at TIMESTAMPTZ(3), ended_at TIMESTAMPTZ(3),
  CONSTRAINT work_actions_project_id_issue_id_fkey FOREIGN KEY (project_id, issue_id) REFERENCES project_issues(project_id,id) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT work_actions_status_check CHECK (status IN ('ready','active','completed','cancelled')),
  CONSTRAINT work_actions_revision_check CHECK (revision > 0 AND sequence > 0)
);
CREATE UNIQUE INDEX work_actions_issue_id_sequence_key ON work_actions(issue_id,sequence);
CREATE INDEX work_actions_handler_id_status_project_id_idx ON work_actions(handler_id,status,project_id);
CREATE UNIQUE INDEX work_actions_one_open_step ON work_actions(issue_id) WHERE status IN ('ready','active');
UPDATE system_workflows SET draft = '{"nodes":[{"id":"planned","name":"规划中","kind":"initial","allowDevelopment":true,"handler":"businessOwner","category":"planning","x":40,"y":40},{"id":"developing","name":"开发中","kind":"normal","allowDevelopment":true,"handler":"developer","category":"development","x":280,"y":40},{"id":"pending_verification","name":"待验证","kind":"normal","allowDevelopment":false,"handler":"qaOwner","category":"verification","x":520,"y":40},{"id":"verifying","name":"验证中","kind":"normal","allowDevelopment":false,"handler":"qaOwner","category":"verification","x":760,"y":40},{"id":"implemented","name":"已实现","kind":"completed","allowDevelopment":false,"handler":"businessOwner","category":"planning","x":1000,"y":40},{"id":"rejected","name":"已拒绝","kind":"cancelled","allowDevelopment":false,"handler":"businessOwner","category":"planning","x":520,"y":240}],"transitions":[{"id":"planned_developing","from":"planned","to":"developing","name":"开始开发","permission":"issue.transition","requiresReason":false},{"id":"developing_pending_verification","from":"developing","to":"pending_verification","name":"提交验证","permission":"issue.transition","requiresReason":false},{"id":"pending_verification_verifying","from":"pending_verification","to":"verifying","name":"开始验证","permission":"issue.accept","requiresReason":false},{"id":"verifying_implemented","from":"verifying","to":"implemented","name":"验证通过","permission":"issue.accept","requiresReason":false},{"id":"developing_planned","from":"developing","to":"planned","name":"退回规划","permission":"issue.transition","requiresReason":true},{"id":"pending_verification_developing","from":"pending_verification","to":"developing","name":"退回开发","permission":"issue.accept","requiresReason":true},{"id":"verifying_developing","from":"verifying","to":"developing","name":"验证失败","permission":"issue.accept","requiresReason":true},{"id":"implemented_planned","from":"implemented","to":"planned","name":"重新打开","permission":"issue.transition","requiresReason":true},{"id":"rejected_planned","from":"rejected","to":"planned","name":"重新规划","permission":"issue.transition","requiresReason":true},{"id":"planned_rejected","from":"planned","to":"rejected","name":"拒绝","permission":"issue.transition","requiresReason":true},{"id":"developing_rejected","from":"developing","to":"rejected","name":"拒绝","permission":"issue.transition","requiresReason":true},{"id":"pending_verification_rejected","from":"pending_verification","to":"rejected","name":"拒绝","permission":"issue.accept","requiresReason":true},{"id":"verifying_rejected","from":"verifying","to":"rejected","name":"拒绝","permission":"issue.accept","requiresReason":true}]}'::jsonb WHERE type = 'requirement';
UPDATE system_workflows SET draft = '{"nodes":[{"id":"pending","name":"待处理","kind":"initial","allowDevelopment":true,"handler":"businessOwner","category":"planning","x":40,"y":40},{"id":"processing","name":"处理中","kind":"normal","allowDevelopment":true,"handler":"developer","category":"development","x":280,"y":40},{"id":"resolved","name":"已解决待验证","kind":"normal","allowDevelopment":false,"handler":"qaOwner","category":"verification","x":520,"y":40},{"id":"verified","name":"已验证待关闭","kind":"normal","allowDevelopment":false,"handler":"acceptanceOwner","category":"verification","x":760,"y":40},{"id":"closed","name":"已关闭","kind":"completed","allowDevelopment":false,"handler":"businessOwner","category":"planning","x":1000,"y":40},{"id":"failed","name":"失败待处理","kind":"normal","allowDevelopment":true,"handler":"developer","category":"development","x":280,"y":240},{"id":"cancelled","name":"已取消","kind":"cancelled","allowDevelopment":false,"handler":"businessOwner","category":"planning","x":760,"y":240}],"transitions":[{"id":"pending_processing","from":"pending","to":"processing","name":"开始处理","permission":"issue.transition","requiresReason":false},{"id":"processing_resolved","from":"processing","to":"resolved","name":"提交验证","permission":"issue.transition","requiresReason":false},{"id":"resolved_verified","from":"resolved","to":"verified","name":"验证通过","permission":"issue.accept","requiresReason":false},{"id":"verified_closed","from":"verified","to":"closed","name":"关闭缺陷","permission":"issue.accept","requiresReason":false},{"id":"resolved_failed","from":"resolved","to":"failed","name":"验证失败","permission":"issue.accept","requiresReason":true},{"id":"verified_failed","from":"verified","to":"failed","name":"退回处理","permission":"issue.accept","requiresReason":true},{"id":"failed_processing","from":"failed","to":"processing","name":"重新处理","permission":"issue.transition","requiresReason":false},{"id":"processing_pending","from":"processing","to":"pending","name":"退回待处理","permission":"issue.transition","requiresReason":true},{"id":"closed_pending","from":"closed","to":"pending","name":"重新打开","permission":"issue.transition","requiresReason":true},{"id":"cancelled_pending","from":"cancelled","to":"pending","name":"恢复处理","permission":"issue.transition","requiresReason":true},{"id":"pending_cancelled","from":"pending","to":"cancelled","name":"取消","permission":"issue.transition","requiresReason":true},{"id":"processing_cancelled","from":"processing","to":"cancelled","name":"取消","permission":"issue.transition","requiresReason":true},{"id":"resolved_cancelled","from":"resolved","to":"cancelled","name":"取消","permission":"issue.accept","requiresReason":true},{"id":"verified_cancelled","from":"verified","to":"cancelled","name":"取消","permission":"issue.accept","requiresReason":true},{"id":"failed_cancelled","from":"failed","to":"cancelled","name":"取消","permission":"issue.transition","requiresReason":true}]}'::jsonb WHERE type = 'bug';
UPDATE system_workflow_versions v SET definition = w.draft FROM system_workflows w WHERE v.workflow_id = w.id;
COMMIT;
